from __future__ import annotations

import json
import os
from collections.abc import Mapping
from typing import Any

from event_store import append_event
from signature_utils import verify_signature

SIGNATURE_HEADER = "X-Webhook-Signature"
REQUIRED_EVENT_FIELDS = ("event_id", "event_type", "account_id")


def _rejected(reason: str) -> dict[str, Any]:
    return {"status": "rejected", "reason": reason}


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and enqueue one payment event."""

    if not isinstance(request, Mapping):
        return _rejected("malformed request")

    headers = request.get("headers")
    body = request.get("body")
    if not isinstance(headers, Mapping) or not isinstance(body, (bytes, bytearray)):
        return _rejected("malformed request")
    body = bytes(body)

    # The receiver guide's relay-era convention made the signature header
    # optional because the relay had already authenticated internal deliveries.
    # Per deployment.json the current route is public ingress with no
    # authenticating middleware, so every delivery must present a valid
    # HMAC-SHA256 signature; unsigned requests are rejected, not accepted.
    secret = os.environ.get("WEBHOOK_SECRET")
    signature = headers.get(SIGNATURE_HEADER)
    if not secret or not verify_signature(body, signature, secret):
        return _rejected("invalid signature")

    try:
        event = json.loads(body.decode("utf-8"))
    except ValueError:
        return _rejected("invalid JSON")

    if not isinstance(event, dict) or any(
        not isinstance(event.get(field), str) for field in REQUIRED_EVENT_FIELDS
    ):
        return _rejected("invalid event")

    # Event fields are passed through unchanged for downstream schema
    # compatibility, per the receiver guide.
    append_event(event)
    return {"status": "accepted", "event_id": event["event_id"]}
